import{_ as t,o,c as i,a2 as e}from"./chunks/framework.CAKCj7G0.js";const u=JSON.parse('{"title":"路由信息","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/09.react/5-2.路由信息.md","filePath":"DuOneClass/09.react/5-2.路由信息.md"}'),r={name:"DuOneClass/09.react/5-2.路由信息.md"};function l(s,a,n,h,c,p){return o(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="路由信息" tabindex="-1">路由信息 <a class="header-anchor" href="#路由信息" aria-label="Permalink to &quot;路由信息&quot;">​</a></h1><p>Router组件会创建一个上下文，并且，向上下文中注入一些信息</p><p>该上下文对开发者是隐藏的，Route组件若匹配到了地址，则会将这些上下文中的信息作为属性传入对应的组件</p><h2 id="history" tabindex="-1">history <a class="header-anchor" href="#history" aria-label="Permalink to &quot;history&quot;">​</a></h2><p>它并不是window.history对象，我们利用该对象无刷新跳转地址</p><p><strong>为什么没有直接使用history对象</strong></p><ol><li>React-Router中有两种模式：Hash、History，如果直接使用window.history，只能支持一种模式</li><li>当使用windows.history.pushState方法时，没有办法收到任何通知，将导致React无法知晓地址发生了变化，结果导致无法重新渲染组件</li></ol><ul><li>push：将某个新的地址入栈（历史记录栈） <ul><li>参数1：新的地址</li><li>参数2：可选，附带的状态数据</li></ul></li><li>replace：将某个新的地址替换掉当前栈中的地址</li><li>go: 与window.history一致</li><li>forward: 与window.history一致</li><li>back: 与window.history一致</li></ul><h2 id="location" tabindex="-1">location <a class="header-anchor" href="#location" aria-label="Permalink to &quot;location&quot;">​</a></h2><p>与history.location完全一致，是同一个对象，但是，与window.location不同</p><p>location对象中记录了当前地址的相关信息</p><p>我们通常使用第三方库<code>query-string</code>，用于解析地址栏中的数据</p><h2 id="match" tabindex="-1">match <a class="header-anchor" href="#match" aria-label="Permalink to &quot;match&quot;">​</a></h2><p>该对象中保存了，路由匹配的相关信息</p><ul><li>isExact：事实上，当前的路径和路由配置的路径是否是精确匹配的</li><li>params：获取路径规则中对应的数据</li></ul><p>实际上，在书写Route组件的path属性时，可以书写一个<code>string pattern</code>（字符串正则）</p><p>react-router使用了第三方库：Path-to-RegExp，该库的作用是，将一个字符串正则转换成一个真正的正则表达式。</p><p><strong>向某个页面传递数据的方式：</strong></p><ol><li>使用state：在push页面时，加入state</li><li><strong>利用search：把数据填写到地址栏中的？后</strong></li><li>利用hash：把数据填写到hash后</li><li><strong>params：把数据填写到路径中</strong></li></ol><h2 id="非路由组件获取路由信息" tabindex="-1">非路由组件获取路由信息 <a class="header-anchor" href="#非路由组件获取路由信息" aria-label="Permalink to &quot;非路由组件获取路由信息&quot;">​</a></h2><p>某些组件，并没有直接放到Route中，而是嵌套在其他普通组件中，因此，它的props中没有路由信息，如果这些组件需要获取到路由信息，可以使用下面两种方式：</p><ol><li>将路由信息从父组件一层一层传递到子组件</li><li>使用react-router提供的高阶组件withRouter，包装要使用的组件，该高阶组件会返回一个新组件，新组件将向提供的组件注入路由信息。</li></ol>',22)])])}const _=t(r,[["render",l]]);export{u as __pageData,_ as default};
